mapper.select:
SELECT id, material_id, material_number, material_name, spec_model, stock_id, stock_name, unit_name, qty, valid_qty, available_out_qty, category_id, category_name, image_url, sync_time FROM kd_inventory
AND material_number LIKE CONCAT('%', #{materialNumber}, '%') AND material_name LIKE CONCAT('%', #{materialName}, '%') AND category_id = #{categoryId}
AND sync_time BETWEEN #{params.beginBillDate} AND #{params.endBillDate}
ORDER BY material_number, stock_name
